package dev.pro8.homeview.direct;
import android.content.*;import android.content.pm.*;import android.database.*;import android.graphics.*;import android.net.Uri;import android.os.*;import java.io.*;import java.util.concurrent.CopyOnWriteArrayList;import org.json.*;
/** Reads a narrow, same-signature metadata provider. No account or playback access. */
final class LocalBilibiliWidget {
 private static final Uri SNAPSHOT=Uri.parse("content://dev.pro8.bili.widget/snapshot");
 private final Context context;private boolean observed;private long stamp;private String coverUri="";private byte[] cover;
 private final CopyOnWriteArrayList<Runnable> listeners=new CopyOnWriteArrayList<>();
 LocalBilibiliWidget(Context context){this.context=context.getApplicationContext();}
 private boolean available(){ProviderInfo p=context.getPackageManager().resolveContentProvider("dev.pro8.bili.widget",0);return p!=null&&"dev.pro8.bili".equals(p.packageName)&&context.getPackageManager().checkSignatures(context.getPackageName(),p.packageName)==PackageManager.SIGNATURE_MATCH;}
 private void observe(){if(observed||!available())return;try{context.getContentResolver().registerContentObserver(SNAPSHOT,true,new ContentObserver(new Handler(Looper.getMainLooper())){public void onChange(boolean self){synchronized(LocalBilibiliWidget.this){cover=null;stamp=0;}for(Runnable task:listeners)task.run();}});observed=true;}catch(RuntimeException ignored){}}
 void watch(Runnable task){listeners.addIfAbsent(task);observe();}void unwatch(Runnable task){listeners.remove(task);}
 private static String text(Cursor c,String key){int i=c.getColumnIndex(key);return i<0||c.isNull(i)?"":c.getString(i);}
 synchronized JSONObject state()throws Exception{observe();if(!available())return NetEaseClient.obj("ok",true,"configured",false,"available",false,"pending",false);
  try(Cursor c=context.getContentResolver().query(SNAPSHOT,null,null,null,null)){if(c==null||!c.moveToFirst())return NetEaseClient.obj("ok",true,"configured",true,"available",false);String uri=text(c,"cover_uri"),id=text(c,"bvid");long at=0;try{at=Long.parseLong(text(c,"updated_at"));}catch(NumberFormatException ignored){}boolean ready="1".equals(text(c,"available"))&&id.matches("BV[A-Za-z0-9]{10}")&&uri.equals("content://dev.pro8.bili.widget/cover/"+id);if(at!=stamp||!uri.equals(coverUri)){stamp=at;coverUri=uri;cover=null;}return NetEaseClient.obj("ok",true,"configured",true,"available",ready,"pending","1".equals(text(c,"pending")),"title",text(c,"title"),"bvid",id,"updated_at",at,"source",text(c,"source"),"cover",ready?"/api/hv/bilibili/widget-cover?v="+at:"");}catch(SecurityException e){return NetEaseClient.obj("ok",true,"configured",false,"available",false,"pending",false);}
 }
 synchronized byte[] image()throws Exception{JSONObject state=state();if(!state.optBoolean("available"))throw new FileNotFoundException();if(cover!=null)return cover;byte[] source;try(InputStream in=context.getContentResolver().openInputStream(Uri.parse(coverUri))){source=NetEaseClient.read(in,1024*1024);}BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(source,0,source.length,opts);if(opts.outWidth<1||opts.outHeight<1||opts.outWidth>4096||opts.outHeight>4096)throw new IOException("封面尺寸不可用");opts.inSampleSize=1;while(opts.outWidth/opts.inSampleSize>512||opts.outHeight/opts.inSampleSize>512)opts.inSampleSize*=2;opts.inJustDecodeBounds=false;Bitmap original=BitmapFactory.decodeByteArray(source,0,source.length,opts);if(original==null)throw new IOException("封面不可用");Bitmap scaled=Bitmap.createScaledBitmap(original,288,162,true),blurred=scaled.copy(Bitmap.Config.ARGB_8888,true);if(original!=scaled)original.recycle();scaled.recycle();blur(blurred,12);ByteArrayOutputStream out=new ByteArrayOutputStream();blurred.compress(Bitmap.CompressFormat.JPEG,82,out);blurred.recycle();cover=out.toByteArray();return cover;}
 /** Three small box passes approximate a Gaussian once per changed cover. */
 private static void blur(Bitmap bitmap,int radius){int width=bitmap.getWidth(),height=bitmap.getHeight(),span=radius*2+1;int[] a=new int[width*height],b=new int[a.length];bitmap.getPixels(a,0,width,0,0,width,height);for(int pass=0;pass<3;pass++){for(int y=0;y<height;y++){int row=y*width,red=0,green=0,blue=0;for(int dx=-radius;dx<=radius;dx++){int pixel=a[row+Math.max(0,Math.min(width-1,dx))];red+=(pixel>>>16)&255;green+=(pixel>>>8)&255;blue+=pixel&255;}for(int x=0;x<width;x++){b[row+x]=0xff000000|(red/span)<<16|(green/span)<<8|blue/span;int remove=a[row+Math.max(0,x-radius)],add=a[row+Math.min(width-1,x+radius+1)];red+=((add>>>16)&255)-((remove>>>16)&255);green+=((add>>>8)&255)-((remove>>>8)&255);blue+=(add&255)-(remove&255);}}for(int x=0;x<width;x++){int red=0,green=0,blue=0;for(int dy=-radius;dy<=radius;dy++){int pixel=b[Math.max(0,Math.min(height-1,dy))*width+x];red+=(pixel>>>16)&255;green+=(pixel>>>8)&255;blue+=pixel&255;}for(int y=0;y<height;y++){a[y*width+x]=0xff000000|(red/span)<<16|(green/span)<<8|blue/span;int remove=b[Math.max(0,y-radius)*width+x],add=b[Math.min(height-1,y+radius+1)*width+x];red+=((add>>>16)&255)-((remove>>>16)&255);green+=((add>>>8)&255)-((remove>>>8)&255);blue+=(add&255)-(remove&255);}}}bitmap.setPixels(a,0,width,0,0,width,height);}

}
